import { FC, ReactNode, useEffect, useState } from "react";
import { loadRemote } from "@module-federation/enhanced/runtime";
import { FeedBackLayout, ModuleBox } from "@norma/core";
import { Illustrations } from "@norma/icons";
import { ErrorBoundary } from "react-error-boundary";

export interface Props {
  request?: string;
  fallback?: () => ReactNode;
}

const DefaultFallback = ({ btnList }: any) => (
  <ModuleBox h="100%">
    <ModuleBox.Content overflow="visible">
      <FeedBackLayout
        typeIcon={
          <>
            <h2 style={{ fontSize: "78px" }}>🎃</h2>
          </>
        }
        mainTitle="🎃 System not found."
        description={`Imposible to load system "${"system"}"`}
        errorCode="401"
        btnList={btnList}
      />
    </ModuleBox.Content>
  </ModuleBox>
);

const DynamicRemote: FC<Props> = ({ request, fallback }) => {
  const [loadCounter, setLoadCounter] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [ComponentRemote, setComponentRemote] = useState<any>(null);

  useEffect(() => {
    setLoading(true);
    loadRemote<{ default: any }>(request || "", {
      from: "runtime",
    })
      .then((module) => {
        setComponentRemote(() => module?.default);
        setError(false);
      })
      .catch(() => {
        setComponentRemote(() => fallback);
        setError(true);
      })
      .finally(() => setLoading(false));
  }, [request, loadCounter]);

  if (loading) return <p>Loading...</p>;
  if (error) {
    return fallback ? (
      fallback()
    ) : (
      <DefaultFallback
        btnList={[
          {
            onClick: () => {
              // navigate("/");
              alert("click 1");
            },
            text: "Ir al inicio",
          },
          {
            onClick: () => setLoadCounter((prev) => prev + 1),
            text: "Volver a cargar",
          },
        ]}
      />
    );
  }

  if (ComponentRemote === null) return;

  return (
    <ErrorBoundary fallback={<p>Pero what a fuck!</p>}>
      <ComponentRemote fallback={<DefaultFallback />} />
    </ErrorBoundary>
  );
};

export default DynamicRemote;
