import { useState } from "react";
import {
  Box,
  Card,
  GridLayout as Grid,
  Link,
  ModuleBox,
  RadioButton,
  SummaryList,
} from "@norma/core";
// import { useAppContext } from "remoteApp/AppContext";

const MySummaryList = ({ label, text }: any) => (
  <SummaryList
    label={label}
    placeholder={{
      text,
      bold: true,
    }}
  />
);

const MyRadioButton = ({ name, value, checked, onChange }: any) => (
  <RadioButton
    position="relative"
    paddingLeft="0px"
    name={name}
    value={value}
    checked={checked}
    onChange={onChange}
  />
);

const MyCard = ({ title, cardSelected, onChange }: any) => {
  return (
    <Card>
      <Card.Header title={title} alignItems="center">
        <Card.Header.Left>
          <MyRadioButton
            name={title}
            value={title}
            checked={title === cardSelected}
            onChange={onChange}
          />
        </Card.Header.Left>
        <Card.Header.Right>
          {/* <IconSvg type="refresh" /> */}
        </Card.Header.Right>
      </Card.Header>
      <Card.Content>
        <Box display="grid" gridTemplateColumns="1fr 1fr" gap="16px">
          <MySummaryList label={"Monto"} text={"$22.400.000"} />
          <MySummaryList label={"Plazo"} text={"36 cuotas"} />
          <MySummaryList label={"Sist. Amortización"} text={"Francés"} />
          <MySummaryList label={"Primera cuota"} text={"01/10/2024"} />
          <MySummaryList label={"Cuota promedio"} text={"380 UVA"} />
        </Box>
        {/* <Box></Box> */}
        <Box display="grid" gridTemplateColumns="1fr 1fr" gap="16px">
          <MySummaryList label={"TNA"} text={"50%"} />
          <MySummaryList label={"CFTEA + IVA"} text={"63,21%"} />
        </Box>
      </Card.Content>
      <Card.Footer>
        <Link>Detalle de cuotas</Link>
        {/* <RemoteButton>Custom text</RemoteButton>
        <RemoteButton variant="secondary">secondary</RemoteButton> */}
      </Card.Footer>
    </Card>
  );
};

