import { PublicRoutes } from "../routes";
import { Navigate, Outlet } from "react-router-dom";

export const AuthGuard = () => {
  const isAthenticated = localStorage.getItem("isAuthenticated") === "true";
  console.log("AuthGuard - isAthenticated:", isAthenticated);

  return isAthenticated ? (
    <Outlet />
  ) : (
    <Navigate replace to={PublicRoutes.LOGIN} />
  );
};

export const RoleGuard = () => {
  const role = localStorage.getItem("role");
  console.log("RoleGuard:", role);

  return role === "admin" ? (
    <Outlet />
  ) : (
    <Navigate replace to={PublicRoutes.FEEDBACK} />
  );
};
